    fftInPlace(re, im, fftSize);
    for (let i = 0; i < fftSize; i++) { re[i] = re[i] * re[i] + im[i] * im[i]; im[i] = 0; }
    // 功率谱为实偶序列，正变换实部 / N 等于自相关。
    fftInPlace(re, im, fftSize);
